// Selection sort: arr holds n values, sorted into ascending order in place.
for ( i <- 0; i < n - 1; i <- i + 1 )
    // Assume the first unsorted slot holds the smallest value ...
    minIndex <- i
    // ... then check every later element to see if that is really true.
    for ( j <- i + 1; j < n; j <- j + 1 )
        if ( arr [ j ] < arr [ minIndex ] )
            minIndex <- j
        end if
    end for
    // Swap the true minimum into position i.
    if ( minIndex != i )
        temp <- arr [ i ]
        arr [ i ] <- arr [ minIndex ]
        arr [ minIndex ] <- temp
    end if
end for
print ( arr )

// global - visible everywhere in this program
int total <- 0

int addTax ( int amount )
{
    int rate <- 8                                 // local to addTax
    int result <- amount + ( amount * rate ) / 100
    amount <- 0                                   // changes the LOCAL copy only
    return result
}

// main program
int price <- 200

total <- addTax ( price )

print ( price )    // what is printed here?
print ( total )    // and here?
