// Variation: the procedure writes the global directly and returns nothing

int total <- 0

void addTaxToTotal ( int amount )
{
    int rate <- 8
    total <- amount + ( amount * rate ) / 100   // assigns the GLOBAL total
}

int price <- 200
addTaxToTotal ( price )
print ( total )     // 216 - same answer, reached a different way

// Model: population grows by a fixed percentage each year

population <- 2000
rate <- 0.08
years <- 4

year <- 0
while ( year < years ) {
    // one step of the simulation = one year
    population <- population * ( 1 + rate )
    year <- year + 1

    print ( year )
    print ( population )
}

// after the loop, population holds the year-4 value
print ( population - 2000 )   // total growth over the run
